		/** 
		 * Tests creating a new Timesheet.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Timesheet");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Timesheet" );

			try {            
				Timesheet entity = TimesheetService.getTimesheetInstance().createTimesheet( generateNewEntity() );
				thePrimaryKey = entity.getTimesheetId();
				LOGGER.info( "-- Successfully created a Timesheet with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Timesheet. 
		 */
		public Timesheet testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Timesheet" );

			Timesheet entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Timesheet with primary key" );
			msg.append( thePrimaryKey );
			
			TimesheetFetchOneSummary fetchOneSummary = new TimesheetFetchOneSummary( thePrimaryKey );

			try {
				entity = TimesheetService.getTimesheetInstance().getTimesheet( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Timesheet " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Timesheet.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Timesheet." );

			StringBuilder msg = new StringBuilder( "Failed to update a Timesheet : " );        
			Timesheet entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Timesheet." );

				// for use later on...
				thePrimaryKey = entity.getTimesheetId();

				TimesheetService proxy = TimesheetService.getTimesheetInstance();            
				proxy.updateTimesheet( entity );   

				LOGGER.info( "-- Successfully saved Timesheet - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Timesheet.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Timesheet." );

			try{
			    Timesheet entity = testRead(); 
				TimesheetService.getTimesheetInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Timesheet with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Timesheet with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Timesheets.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Timesheets:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Timesheet : " );        
			List<Timesheet> collection  = null;

			try {
				// call the static get method on the TimesheetService
				collection = TimesheetService.getTimesheetInstance().getAllTimesheet();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Timesheet entity = null;            
					Iterator<Timesheet> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getTimesheetId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

